import sys
from collections import deque

def main():
    data = sys.stdin.read().split()
    begin, end, n = data[0], data[1], int(data[2])
    words = data[3:3 + n]
    if end not in set(words):
        print(0)
        return
    buckets = {}
    for w in [begin] + words:
        for i in range(len(w)):
            buckets.setdefault(w[:i] + '*' + w[i + 1:], []).append(w)
    dist = {begin: 0}
    parents = {begin: []}
    q = deque([begin])
    while q:
        u = q.popleft()
        if end in dist and dist[u] >= dist[end]:
            break
        for i in range(len(u)):
            for v in buckets[u[:i] + '*' + u[i + 1:]]:
                if v == u:
                    continue
                if v not in dist:
                    dist[v] = dist[u] + 1
                    parents[v] = []
                    q.append(v)
                if dist[v] == dist[u] + 1:
                    parents[v].append(u)
    if end not in dist:
        print(0)
        return
    res = []
    stack = [(end, None)]
    while stack:
        u, later = stack.pop()
        chain = (u, later)
        if u == begin:
            seq = []
            node = chain
            while node:
                seq.append(node[0])
                node = node[1]
            res.append(seq)
        else:
            for p in parents[u]:
                stack.append((p, chain))
    res.sort()
    out = [str(len(res))]
    for seq in res:
        out.append(' '.join(seq))
    print('\n'.join(out))

main()

