def gen(rng):
    import itertools

    def fmt(b, e, words):
        return f"{b} {e}\n{len(words)}\n" + ' '.join(words)

    def bfs_ways(b, words):
        buckets = {}
        for w in [b] + words:
            for i in range(len(w)):
                buckets.setdefault(w[:i] + '*' + w[i + 1:], []).append(w)
        dist = {b: 0}
        ways = {b: 1}
        frontier = [b]
        while frontier:
            nxt = []
            for u in frontier:
                for i in range(len(u)):
                    for v in buckets[u[:i] + '*' + u[i + 1:]]:
                        if v == u:
                            continue
                        if v not in dist:
                            dist[v] = dist[u] + 1
                            ways[v] = 0
                            nxt.append(v)
                        if dist[v] == dist[u] + 1:
                            ways[v] += ways[u]
            frontier = nxt
        return dist, ways

    def rand_case(n, L, alpha, want_far=True):
        cap = len(alpha) ** L
        n = min(n, cap - 1)
        for _ in range(200):
            pool = set()
            while len(pool) < n + 1:
                pool.add(''.join(rng.choice(alpha) for _ in range(L)))
            pool = sorted(pool)
            rng.shuffle(pool)
            b = pool[0]
            words = pool[1:]
            dist, ways = bfs_ways(b, words)
            cands = [w for w in words if 1 <= ways.get(w, 0) <= 1000]
            if not cands:
                continue
            if want_far:
                mx = max(dist[w] for w in cands)
                cands = [w for w in cands if dist[w] == mx]
            e = rng.choice(cands)
            return fmt(b, e, words)
        return None

    def chain(n, L, alpha):
        for _ in range(50):
            cur = ''.join(rng.choice(alpha) for _ in range(L))
            allw = [cur]
            guard = 0
            while len(allw) < n + 1 and guard < 200000:
                guard += 1
                i = rng.randrange(L)
                c = rng.choice(alpha)
                nw = cur[:i] + c + cur[i + 1:]
                if nw == cur:
                    continue
                if any(sum(p != q for p, q in zip(nw, x)) <= 1 for x in allw[:-1]):
                    continue
                allw.append(nw)
                cur = nw
            if len(allw) == n + 1:
                b = allw[0]
                words = allw[1:]
                e = words[-1]
                rng.shuffle(words)
                return fmt(b, e, words)
        return None

    tests = [fmt('hog', 'dot', ['dog', 'hot', 'dot', 'log']),
             fmt('abc', 'xyz', ['abd', 'xyz']),
             fmt('a', 'c', ['b', 'c']),
             fmt('a', 'b', ['b']),
             fmt('abc', 'abd', ['abd']),
             fmt('abc', 'abd', ['abe', 'abf']),
             fmt('aa', 'bb', ['ab', 'ba', 'bb']),
             fmt('aaa', 'bbb', ['aab', 'abb', 'bbb', 'bab', 'baa']),
             fmt('ab', 'ba', ['aa', 'bb', 'ba', 'bc', 'ac', 'cb'])]
    for n, L, alpha in [(3, 2, 'ab'), (5, 2, 'abc'), (6, 3, 'ab'), (7, 3, 'abc'), (8, 3, 'abc'), (6, 4, 'ab'), (8, 2, 'abcd'), (7, 4, 'abc')]:
        for _ in range(2):
            t = rand_case(n, L, alpha, want_far=rng.random() < 0.7)
            if t:
                tests.append(t)
    for n, L, alpha in [(4, 2, 'abc'), (6, 3, 'abc'), (7, 3, 'ab')]:
        pool = sorted(set(''.join(rng.choice(alpha) for _ in range(L)) for _ in range(n + 1)))
        b = pool[0]
        words = pool[1:]
        if words:
            tests.append(fmt(b, rng.choice(words) if rng.random() < 0.5 else 'z' * L, words))
    tests.append(fmt('a' * 6, 'b' * 6, [''.join(p) for p in itertools.product('ab', repeat=6) if ''.join(p) != 'a' * 6]))
    tests.append(rand_case(1000, 7, 'abc'))
    tests.append(rand_case(1000, 7, 'abc', want_far=False))
    tests.append(rand_case(1000, 5, 'abcdefghij'))
    tests.append(rand_case(1000, 3, 'abcdefghi'))
    tests.append(rand_case(1000, 4, 'abcdef'))
    tests.append(rand_case(500, 6, 'abc'))
    tests.append(chain(900, 10, 'abcdefghijklmnopqrstuvwxyz'))
    tests.append(chain(950, 10, 'abcdefghijklmnopqrstuvwxyz'))
    tests.append(chain(400, 6, 'abcdefghijklmnopqrstuvwxyz'))
    return [t for t in tests if t]

